create extension if not exists pgcrypto;
create table if not exists users (id text primary key default gen_random_uuid()::text, username text unique not null, email text unique, password_hash text, name text not null, role text not null default 'user' check(role in('admin','user')), tier text not null default 'สมาชิกทั่วไป', credit numeric not null default 0, status text not null default 'active', line_user_id text unique, line_link_code text unique, created_at timestamptz not null default now());
create table if not exists slots (id text primary key, code text not null, floor int not null, slot_order int not null default 0, status text not null default 'available' check(status in('available','booked','unavailable')), type text not null default 'ปกติ', updated_at timestamptz not null default now());
create table if not exists bookings (id text primary key default gen_random_uuid()::text, slot_id text not null references slots(id) on delete cascade, user_id text not null references users(id) on delete cascade, date date not null, time time not null, duration int not null check(duration>0), amount numeric not null, status text not null default 'pending' check(status in('pending','active','completed','cancelled','no_show')), notified boolean not null default false, notify_before_min int not null default 15, entry_time timestamptz, exit_time timestamptz, actual_minutes int not null default 0, overtime_minutes int not null default 0, overtime_amount numeric not null default 0, entry_verified boolean not null default false, no_show_checked boolean not null default false, created_at timestamptz not null default now());
create table if not exists credit_history (id text primary key default gen_random_uuid()::text,user_id text not null references users(id) on delete cascade,type text not null check(type in('add','reduce')),amount numeric not null,reason text not null,source text not null default 'system',date timestamptz not null default now());
create table if not exists devices (id text primary key,name text not null,type text not null check(type in('barrier','sensor')),floor int not null,status text not null default 'offline',state text check(state in('open','closed')),linked_slot text references slots(id) on delete set null,presence text not null default 'unknown' check(presence in('unknown','occupied','empty')),car_present boolean,updated_at timestamptz not null default now());
create table if not exists credit_requests (id text primary key default gen_random_uuid()::text,user_id text not null references users(id) on delete cascade,type text not null default 'add' check(type in('add','reduce')),amount numeric not null check(amount>0),reason text not null,status text not null default 'pending' check(status in('pending','approved','rejected')),reviewed_by text references users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists maintenance_logs (id text primary key default gen_random_uuid()::text,slot_id text references slots(id),problem_detail text not null,status text not null default 'open',created_at timestamptz not null default now(),resolved_at timestamptz);
create index if not exists bookings_status_idx on bookings(status);
create index if not exists bookings_user_idx on bookings(user_id);
